<template><view class="create-page"><view class="page-heading"><button class="back" @click="back">‹</button><view><text class="ui-kicker">MAKE YOUR OWN MEME</text><text class="title">把灵感做成模板</text></view></view><view v-if="!session" class="login-panel"><text>你的模板，先认领一个小窝。</text><button class="ui-primary" :loading="loggingIn" @click="login">微信一键登录</button></view><template v-else><view class="mode-switch"><button :class="{chosen:mode==='manual'}" @click="mode='manual'">⌗ 拖拽制作</button><button :class="{chosen:mode==='ai'}" @click="mode='ai'">✦ AI 识图制模</button></view><template v-if="mode==='manual'"><view class="step-note"><text>01 摆好画面 → 02 改好文字 → 03 私藏或发布</text><text>照片示意默认用你的头像，生成时会换成用户选的图。</text></view><input class="name-input" v-model="name" maxlength="40" placeholder="给你的梗起个名字"/><view class="canvas-wrap"><view class="design-canvas" :style="{background:backgroundColor,width:canvasSize+'px',height:canvasSize+'px'}" @click="selected=-1"><image v-if="background" :src="background" mode="aspectFill" class="canvas-background"/><view v-for="(layer,index) in layers" :key="layer.uid" class="design-layer" :class="{selected:selected===index,caption:layer.type==='text'}" :style="layerStyle(layer)" @click.stop="selected=index" @touchstart.stop="begin($event,index,false)" @touchmove.stop.prevent="move" @touchend="end" @touchcancel="end" @mousedown.stop.prevent="begin($event,index,false)" @mousemove="move" @mouseup="end" @mouseleave="end"><image v-if="layer.type==='subject'" :src="avatar" :mode="layer.fit==='cover'?'aspectFill':'aspectFit'"/><text v-else :style="{fontSize:(layer.font_size/512*canvasSize)+'px',color:layer.color,textAlign:layer.align}">{{layer.value || '在这里写梗'}}</text><view v-if="selected===index" class="resize-handle" @touchstart.stop.prevent="begin($event,index,true)" @mousedown.stop.prevent="begin($event,index,true)">↘</view></view></view></view><text class="canvas-hint">拖动画面里的图层移动位置，拉右下角可调整大小。</text><view class="tools"><button @click="addSubject">＋ 照片位</button><button @click="addText">＋ 文字位</button><button @click="chooseBackground">{{background?'更换背景':'＋ 背景图'}}</button></view><button v-if="background" class="background-edit" :disabled="busy" @click="backgroundEditor=true"><ui-icon name="cutout" tone="accent" :size="32"/> 编辑背景图 · 裁剪 / 去除背景</button><view class="swatches"><text>底色</text><button v-for="color in colors" :key="color" :style="{background:color}" :class="{picked:backgroundColor===color}" @click="setColor(color)"/><button v-if="background" class="clear-bg" @click="background='';record('remove-background')">去背景图</button></view><view v-if="selectedLayer" class="layer-panel"><view class="layer-heading"><text>{{selectedLayer.type==='text'?'文字图层':'照片占位'}} {{selected+1}}</text><button @click="removeLayer">移除 ×</button></view><template v-if="selectedLayer.type==='text'"><textarea v-model="selectedLayer.value" maxlength="100" placeholder="输入默认文字" auto-height @blur="record('edit-text')"/><view class="inline-tools"><button @click="font(-4)">A−</button><text>{{selectedLayer.font_size}}</text><button @click="font(4)">A＋</button><button @click="selectedLayer.color=selectedLayer.color==='#222222'?'#ffffff':'#222222';record('text-color')">黑 / 白</button></view></template><view v-else class="inline-tools"><button @click="selectedLayer.fit='contain';record('fit-contain')" :class="{active:selectedLayer.fit==='contain'}">完整显示</button><button @click="selectedLayer.fit='cover';record('fit-cover')" :class="{active:selectedLayer.fit==='cover'}">铺满占位</button></view><text class="layer-help">图层可重复替换，作品生成时保留这个位置和大小。</text></view><view class="save-panel"><label class="consent"><checkbox :checked="rights" color="#ed865f" @click="rights=!rights"/><text>发布时，我确认有权使用并公开这些素材。</text></label><view class="save-actions"><button class="ui-secondary" :disabled="busy" @click="save(false)">私藏到我的模板</button><button class="ui-primary" :disabled="busy || !rights" :loading="busy" @click="save(true)">检查并发布 ↗</button></view><text class="fine-print">私藏仅自己可见；发布需通过内容检查，也会存入我的模板。</text></view></template><template v-else><view class="ai-intro"><text class="ai-spark">✦</text><text class="ai-title">丢来一个梗，拆成可改的模板</text><text>保留表情、动作和场景，自动识别可靠的文字区。复杂布局可转手动制作。</text><text class="quota">每天 1 次 · 今日剩余 {{quota?.remaining ?? '…'}} 次</text></view><button class="ai-upload" :disabled="busy" @click="chooseAI"><image v-if="aiPhoto" :src="aiPhoto" mode="aspectFit"/><text v-else>＋ 上传一张静态表情图</text></button><label class="consent"><checkbox :checked="aiRights" color="#ed865f" @click="aiRights=!aiRights"/><text>我有权制作与发布这张图，成功且检查通过后自动加入模板仓库。</text></label><button class="ui-primary ai-submit" :loading="busy" :disabled="busy || !aiPhoto || !aiRights || quota?.remaining===0" @click="submitAI">交给 AI 拆模板 ✦</button><text class="fine-print">这个魔法有点慢，提交后可以离开，稍后到“我的模板”领取。未通过检查的模板仅自己可见。</text></template><view v-if="success" class="success-panel"><text>{{success}}</text><image v-if="resultPreview" :src="resultPreview" mode="aspectFit"/><button class="ui-secondary" @click="goMine">去我的模板看看 ↗</button></view></template><text v-if="error" class="error">{{error}}</text><image-editor v-if="backgroundEditor && background" :src="background" :busy="busy" :error="error" :can-undo="backgroundHistory.length>0" @close="backgroundEditor=false" @edit="editBackground" @undo="undoBackground" @restore="restoreBackground"/><generation-notice/><first-use-guide/></view></template>
<script setup>
import GenerationNotice from '@/components/GenerationNotice.vue'
import FirstUseGuide from '@/components/FirstUseGuide.vue'
import {ref,computed,watch} from 'vue'
import {onShow,onUnload} from '@dcloudio/uni-app'
import ImageEditor from '@/components/ImageEditor.vue'
import UiIcon from '@/components/UiIcon.vue'
import {editImage,removeImageBackground,disposeEditedImage} from '@/services/imageEditing'
import {useLibrary} from '@/composables/useLibrary'
import {createTemplate,encodePhoto,submitAITemplate,templateQuota,uniqueKey,trackStudioJob,privateImage} from '@/services/studioService'
const account=useLibrary(),{session,loggingIn}=account,mode=ref('manual'),name=ref('我的专属梗'),background=ref(''),backgroundColor=ref('#ffffff'),layers=ref([{uid:1,type:'subject',box:[76,30,360,350],fit:'contain'},{uid:2,type:'text',box:[24,398,464,88],value:'今天也要快乐整活',font_size:36,color:'#222222',align:'center'}]),selected=ref(1),busy=ref(false),error=ref(''),success=ref(''),resultPreview=ref(''),aiPhoto=ref(''),rights=ref(false),aiRights=ref(false),quota=ref(null)
const colors=['#ffffff','#fff3e5','#e7f0e3','#ffdfc7','#f9e4e7','#e4edf4'],operations=[],canvasSize=Math.min((uni.getWindowInfo?.().windowWidth||375)-44,420)
const avatar=computed(()=>session.value?.profile.avatarPath||'/static/logo-subject.png'),selectedLayer=computed(()=>layers.value[selected.value])
const backgroundEditor=ref(false),backgroundHistory=ref([])
let editEpoch=0,backgroundOriginal=''
const editedBackgrounds=new Set()
const clearBackgroundEdits=()=>{editEpoch++;for(const path of editedBackgrounds)disposeEditedImage(path);editedBackgrounds.clear();backgroundHistory.value=[];backgroundEditor.value=false}
const editBackground=async operation=>{if(busy.value || !background.value)return;const path=background.value,epoch=++editEpoch,owner=session.value?.profile?.id;busy.value=true;error.value='';try{const output=operation.type==='background'?await removeImageBackground(path):await editImage(path,operation);if(epoch!==editEpoch || owner!==session.value?.profile?.id){disposeEditedImage(output);return}backgroundHistory.value.push(path);editedBackgrounds.add(output);background.value=output;record(operation.type==='background'?'cutout-background':'edit-background');if(operation.complete)backgroundEditor.value=false}catch(e){if(epoch===editEpoch)error.value=e.message||'处理失败，原图已保留'}finally{if(epoch===editEpoch)busy.value=false}}
const undoBackground=()=>{if(!busy.value && backgroundHistory.value.length)background.value=backgroundHistory.value.pop()}
const restoreBackground=()=>{if(!busy.value){background.value=backgroundOriginal;backgroundHistory.value=[]}}
onUnload(clearBackgroundEdits)
let gesture=null,aiKey='',uid=3
const record=action=>{operations.push({action,time:Date.now(),layers:layers.value.map(l=>({type:l.type,box:[...l.box]}))});if(operations.length>60)operations.shift()}
const layerStyle=l=>({left:l.box[0]/512*100+'%',top:l.box[1]/512*100+'%',width:l.box[2]/512*100+'%',height:l.box[3]/512*100+'%'})
const begin=(e,index,resize)=>{const t=e.touches?.[0]||e;selected.value=index;gesture={index,resize,x:t.clientX,y:t.clientY,box:[...layers.value[index].box]}}
const move=e=>{if(!gesture||(!e.touches&&!e.buttons))return;const t=e.touches?.[0]||e,g=gesture,dx=(t.clientX-g.x)/canvasSize*512,dy=(t.clientY-g.y)/canvasSize*512,[x,y,w,h]=g.box;layers.value[g.index].box=g.resize?[x,y,Math.round(Math.max(40,Math.min(512-x,w+dx))),Math.round(Math.max(35,Math.min(512-y,h+dy)))]:[Math.round(Math.max(0,Math.min(512-w,x+dx))),Math.round(Math.max(0,Math.min(512-h,y+dy))),w,h]}
const end=()=>{if(gesture)record(gesture.resize?'resize':'move');gesture=null}
const addSubject=()=>{if(layers.value.filter(l=>l.type==='subject').length>=2){error.value='每个模板最多放 2 张可替换照片';return}layers.value.push({uid:uid++,type:'subject',box:[50,60,260,280],fit:'contain'});selected.value=layers.value.length-1;record('add-subject')}
const addText=()=>{if(layers.value.filter(l=>l.type==='text').length>=2){error.value='先把这两段文字玩明白吧，每个模板最多 2 段';return}layers.value.push({uid:uid++,type:'text',box:[24,380,464,90],value:'在这里写梗',font_size:36,color:'#222222',align:'center'});selected.value=layers.value.length-1;record('add-text')}
const removeLayer=()=>{layers.value.splice(selected.value,1);selected.value=layers.value.length-1;record('remove-layer')}
const font=delta=>{selectedLayer.value.font_size=Math.min(100,Math.max(10,selectedLayer.value.font_size+delta));record('font-size')}
const setColor=color=>{backgroundColor.value=color;record('canvas-color')}
const chooseBackground=()=>{if(busy.value)return;const owner=session.value?.profile?.id;uni.chooseImage({count:1,sizeType:['compressed'],success:r=>{if(owner!==session.value?.profile?.id)return;clearBackgroundEdits();backgroundOriginal=r.tempFilePaths[0];background.value=backgroundOriginal;backgroundEditor.value=true;record('background-image')}})}
const chooseAI=()=>uni.chooseImage({count:1,sizeType:['compressed'],success:r=>{aiPhoto.value=r.tempFilePaths[0];aiKey=uniqueKey();error.value=''}})
const login=async()=>{try{await account.loginWeChat();loadQuota()}catch(e){error.value=e.message}}
const loadQuota=()=>{const owner=session.value?.profile?.id;if(owner)templateQuota().then(q=>{if(owner===session.value?.profile?.id)quota.value=q}).catch(()=>{})};onShow(loadQuota)
watch(()=>session.value?.profile?.id,(next,old)=>{if(old&&next!==old){clearBackgroundEdits();busy.value=false;background.value='';aiPhoto.value='';resultPreview.value='';success.value='';rights.value=false;aiRights.value=false;name.value='我的专属梗';layers.value=[{uid:uid++,type:'subject',box:[76,30,360,350],fit:'contain'},{uid:uid++,type:'text',box:[24,398,464,88],value:'今天也要快乐整活',font_size:36,color:'#222222',align:'center'}];selected.value=1;operations.splice(0);error.value='账号已切换，请重新选取素材'}})
const save=async publish=>{if(busy.value)return;if(!name.value.trim()){error.value='给这个梗起个名字吧';return}if(!layers.value.length){error.value='加一个照片位或文字位再保存吧';return}busy.value=true;error.value='';success.value='';const owner=session.value?.profile?.id;try{let imageSlot=0,textSlot=0;const defaults=[],compiled=[];if(background.value)compiled.push({type:'asset',box:[0,0,512,512],value:'0'.repeat(64),fit:'cover'});for(const l of layers.value){if(l.type==='subject')compiled.push({type:'subject',box:l.box,slot:imageSlot++,fit:l.fit});else{defaults.push(l.value||'你的梗');compiled.push({type:'text',box:l.box,slot:textSlot++,value:l.value||'你的梗',font_size:l.font_size,color:l.color,align:'center'})}}const background_image=background.value?await encodePhoto(background.value):'';if(owner!==session.value?.profile?.id)throw Error('账号已切换，请重新选取素材');const data=await createTemplate({name:name.value.trim(),spec:{width:512,height:512,background:backgroundColor.value,layers:compiled,defaults},background_image,operations,publish,rights_attested:rights.value});if(owner!==session.value?.profile?.id)return;if(data.publication_job)trackStudioJob(data.publication_job);success.value=data.message;const previewPath=await privateImage(data.preview_url).catch(()=>'');if(owner!==session.value?.profile?.id)return;resultPreview.value=previewPath;uni.setStorageSync('gensticker.templates.changed',true)}catch(e){error.value=e.message||'保存失败，素材还在，请重试'}finally{busy.value=false}}
const submitAI=async()=>{if(busy.value)return;busy.value=true;error.value='';const owner=session.value?.profile?.id;try{const data=await submitAITemplate(aiPhoto.value,aiKey||uniqueKey(),aiRights.value);if(owner!==session.value?.profile?.id)return;trackStudioJob(data);quota.value={remaining:0};success.value='已经接单啦！稍后到我的模板看看，小窝做好会喊你。';uni.setStorageSync('gensticker.templates.changed',true)}catch(e){error.value=e.message}finally{busy.value=false}}
const goMine=()=>{uni.setStorageSync('gensticker.open-mine',true);uni.switchTab({url:'/pages/index/index'})},back=()=>getCurrentPages().length>1?uni.navigateBack():uni.switchTab({url:'/pages/index/index'})
</script>
<style scoped>
.create-page{min-height:100vh;padding:calc(110rpx + env(safe-area-inset-top)) 28rpx calc(50rpx + env(safe-area-inset-bottom));background:var(--paper)}.page-heading{display:flex;align-items:center;gap:20rpx;margin-bottom:26rpx}.back{font-size:54rpx;width:60rpx;color:var(--ink)}.title{display:block;font-size:36rpx;font-weight:800}.mode-switch{display:flex;background:#eee9de;border-radius:24rpx;padding:7rpx;gap:8rpx}.mode-switch button{flex:1;font-size:26rpx;color:#8f9280;border-radius:20rpx;padding:20rpx 8rpx;line-height:1.5}.mode-switch .chosen{background:#fff;color:#c57652;box-shadow:0 4rpx 0 #e4d6c5}.step-note{padding:24rpx 0;color:#a19b8d;font-size:22rpx;line-height:1.8}.step-note text{display:block}.step-note text:first-child{color:#9b815d;font-weight:600}.name-input{height:90rpx;border-radius:22rpx;background:#fff;border:2rpx solid #eee5db;padding:0 22rpx;font-size:28rpx;margin:4rpx 0 24rpx}.canvas-wrap{background:#f4eee4;padding:10rpx;border:3rpx solid white;border-radius:22rpx;box-shadow:0 6rpx 0 #e9dece}.design-canvas{position:relative;width:100%;aspect-ratio:1;height:calc(100vw - 83rpx);max-height:420px;overflow:hidden;touch-action:none}.canvas-background{position:absolute;inset:0;width:100%;height:100%}.design-layer{position:absolute;display:flex;align-items:center;justify-content:center;border:2rpx solid transparent;touch-action:none;user-select:none}.design-layer.selected{border:2rpx dashed #ee8b66}.design-layer image{width:100%;height:100%;pointer-events:none}.design-layer.caption{align-items:flex-start}.design-layer text{display:block;line-height:1.25;width:100%;overflow:hidden;pointer-events:none;word-break:break-all}.resize-handle{position:absolute;bottom:-8rpx;right:-8rpx;width:48rpx;height:48rpx;background:#ed936e;color:white;border:3rpx solid white;border-radius:15rpx;text-align:center;line-height:42rpx;font-size:30rpx}.canvas-hint{display:block;color:#a19a8b;font-size:22rpx;margin:22rpx 0}.tools{display:flex;gap:12rpx}.tools button{flex:1;border-radius:20rpx;background:#fff0e0;color:#ba805d;font-size:24rpx;padding:20rpx 6rpx;line-height:1.5}.swatches{display:flex;align-items:center;gap:14rpx;margin:24rpx 0;color:#959380;font-size:23rpx}.swatches button{width:46rpx;height:46rpx;border:3rpx solid white;border-radius:50%;box-shadow:0 2rpx 0 #d6cbb9}.swatches .picked{border-color:#df9a6e}.swatches .clear-bg{width:auto;border:0;background:none;box-shadow:none;color:#b98162;font-size:20rpx}.layer-panel{background:white;border-radius:28rpx;padding:24rpx;border:2rpx solid #f1e7db}.layer-heading{display:flex;justify-content:space-between;font-size:26rpx;font-weight:650}.layer-heading button{color:#c17e63;font-size:23rpx}.layer-panel textarea{width:100%;min-height:90rpx;font-size:28rpx;background:#faf6f0;border-radius:16rpx;padding:18rpx;margin-top:20rpx}.inline-tools{display:flex;align-items:center;gap:18rpx;margin:20rpx 0}.inline-tools button{padding:12rpx 18rpx;background:#f3eee6;border-radius:14rpx;font-size:24rpx;color:#8b8c7a}.inline-tools .active{color:#ce805a;background:#fff0e3}.layer-help,.fine-print{display:block;font-size:21rpx;color:#aaa18e;line-height:1.7}.save-panel{margin-top:30rpx}.consent{display:flex;align-items:center;font-size:22rpx;color:#9a927f;line-height:1.7;margin:24rpx 0}.consent checkbox{transform:scale(.75);flex-shrink:0}.save-actions{display:flex;gap:15rpx;margin-bottom:18rpx}.save-actions button{flex:1;font-size:24rpx;padding:20rpx 10rpx;line-height:1.6}.ai-intro{padding:35rpx 10rpx 20rpx;text-align:center}.ai-intro text{display:block;color:#9b937f;font-size:24rpx;line-height:1.8}.ai-intro .ai-spark{font-size:90rpx;color:#e2ab68;animation:ui-float 3s ease-in-out infinite}.ai-intro .ai-title{color:var(--ink);font-size:30rpx;font-weight:700;margin-bottom:10rpx}.quota{margin-top:20rpx;font-weight:650;color:#bb8c59!important}.ai-upload{width:100%;height:340rpx;background:#fff5e9;border:2rpx dashed #e5cfb3;border-radius:28rpx;color:#b48862;font-size:27rpx;display:flex;align-items:center;justify-content:center}.ai-upload image{width:100%;height:100%}.ai-submit{width:100%;margin:25rpx 0}.success-panel{background:#eaf1e2;border-radius:28rpx;padding:25rpx;margin-top:28rpx;color:#64805f;line-height:1.8;font-size:24rpx}.success-panel image{display:block;width:100%;height:300rpx;margin:20rpx 0}.success-panel button{width:100%;margin-top:20rpx}.error{display:block;background:#fff0e5;color:#af6d52;border-radius:20rpx;font-size:24rpx;padding:20rpx;margin-top:20rpx}.login-panel{padding:40rpx 10rpx;color:#a19580}.login-panel button{margin-top:25rpx}
.background-edit{display:flex;align-items:center;justify-content:center;gap:12rpx;width:100%;margin-top:20rpx;padding:20rpx;background:#e8f0e0;border-radius:20rpx;font-size:25rpx;color:#718963}
</style>
